14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    let mut current_cmd = &*cmd;
36	    if cmd.is_multicall_set() {
37	        // A multicall executable dispatches on the file name of argv0 (the
38	        // "applet"), falling back to the first argument when invoked through
39	        // its canonical or an unrecognized name, e.g. `busybox inspect`.
40	        let applet = raw_args
41	            .next_os(&mut cursor)
42	            .and_then(|argv0| std::path::Path::new(argv0).file_stem().map(OsStr::to_owned));
43	        if let Some(applet) = applet.as_deref().and_then(OsStr::to_str) {
44	            if let Some(subcmd) = cmd.find_subcommand(applet) {
45	                debug!("complete: multicall applet={applet:?}");
46	                current_cmd = subcmd;
47	            } else {
48	                // Unknown applet name: only continue when the next argument
49	                // names a known applet; otherwise there is nothing to complete.
50	                let mut peek = cursor.clone();
51	                let is_launcher = raw_args
52	                    .next_os(&mut peek)
53	                    .and_then(OsStr::to_str)
54	                    .is_some_and(|next| cmd.find_subcommand(next).is_some());
55	                if !is_launcher {
56	                    debug!("complete: unrecognized multicall applet={applet:?}");
57	                    return Ok(Vec::new());
58	                }
59	            }
60	        }
61	    } else if !cmd.is_no_binary_name_set() {
62	        raw_args.next_os(&mut cursor);
63	    }
64	    let mut pos_index = 1;
65	    let mut is_escaped = false;
66	    let mut next_state = ParseState::ValueDone;
67	    while let Some(arg) = raw_args.next(&mut cursor) {
68	        let current_state = next_state;
69	        next_state = ParseState::ValueDone;
70	        debug!(
71	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
72	            arg.to_value_os(),
73	        );
74	        if cursor == target_cursor {
75	            return complete_arg(
76	                &arg,
77	                current_cmd,
78	                current_dir,
79	                pos_index,
80	                is_escaped,
81	                current_state,
82	            );
83	        }
84	
85	        if let Ok(value) = arg.to_value() {
86	            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
87	                current_cmd = next_cmd;
88	                pos_index = 1;
89	                continue;
90	            }
91	        }
92	
93	        if is_escaped {
94	            (next_state, pos_index) =
95	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
96	        } else if arg.is_escape() {
97	            is_escaped = true;
98	        } else if opt_allows_hyphen(&current_state, &arg) {
99	            match current_state {
100	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
101	                _ => unreachable!("else branch is only reachable in Opt state"),
102	            }
103	        } else if let Some((flag, value)) = arg.to_long() {
104	            if let Ok(flag) = flag {
105	                let opt = current_cmd.get_arguments().find(|a| {
106	                    let longs = a.get_long_and_visible_aliases();
107	                    let is_find = longs.map(|v| {
108	                        let mut iter = v.into_iter();
109	                        let s = iter.find(|s| *s == flag);
110	                        s.is_some()
111	                    });
112	                    is_find.unwrap_or(false)
113	                });
114	
115	                if let Some(opt) = opt {
116	                    if opt.get_num_args().expect("built").takes_values() && value.is_none() {
117	                        next_state = ParseState::Opt((opt, 1));
118	                    };
119	                } else if pos_allows_hyphen(current_cmd, pos_index) {
120	                    (next_state, pos_index) =
121	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
122	                } else {
123	                    debug!("complete: unknown flag={flag:?}");
124	                    return Ok(Vec::new());
125	                }
126	            }
127	        } else if let Some(short) = arg.to_short() {
128	            let (_, takes_value_opt, mut short) = parse_shortflags(current_cmd, short);
129	            if let Some(opt) = takes_value_opt {
130	                if short.next_value_os().is_none() {
131	                    next_state = ParseState::Opt((opt, 1));
132	                }
133	            } else if pos_allows_hyphen(current_cmd, pos_index) {
134	                (next_state, pos_index) =
135	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
136	            }
137	        } else {
138	            match current_state {
139	                ParseState::ValueDone | ParseState::Pos(..) => {
140	                    if current_cmd
141	                        .get_positionals()
142	                        .all(|p| p.get_index() != Some(pos_index))
143	                    {
144	                        debug!("complete: unrecognized argument={:?}", arg.to_value_os());
145	                        return Ok(Vec::new());
146	                    }
147	                    (next_state, pos_index) =
148	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
149	                }
150	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
151	            }
152	        }
153	    }
154	
155	    Err(std::io::Error::other("no completion generated"))
156	}
