158	#[derive(Debug, PartialEq, Eq, Clone)]
159	enum ParseState<'a> {
160	    /// Parsing a value done, there is no state to record.
161	    ValueDone,
162	
163	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
164	    Pos((usize, usize)),
165	
166	    /// Parsing a optional flag argument
167	    Opt((&'a clap::Arg, usize)),
168	}
