282	fn complete_option(
283	    arg: &clap_lex::ParsedArg<'_>,
284	    cmd: &clap::Command,
285	    current_dir: Option<&std::path::Path>,
286	) -> Vec<CompletionCandidate> {
287	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
288	    let mut completions = Vec::<CompletionCandidate>::new();
289	    if arg.is_empty() {
290	        completions.extend(longs_and_visible_aliases(cmd));
291	        completions.extend(hidden_longs_aliases(cmd));
292	
293	        let dash_or_arg = if arg.is_empty() {
294	            "-".into()
295	        } else {
296	            arg.to_value_os().to_string_lossy()
297	        };
298	        completions.extend(
299	            shorts_and_visible_aliases(cmd)
300	                .into_iter()
301	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
302	        );
303	    } else if arg.is_stdio() {
304	        // HACK: Assuming knowledge of is_stdio
305	        let dash_or_arg = if arg.is_empty() {
306	            "-".into()
307	        } else {
308	            arg.to_value_os().to_string_lossy()
309	        };
310	        completions.extend(
311	            shorts_and_visible_aliases(cmd)
312	                .into_iter()
313	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
314	        );
315	
316	        completions.extend(longs_and_visible_aliases(cmd));
317	        completions.extend(hidden_longs_aliases(cmd));
318	    } else if arg.is_escape() {
319	        // HACK: Assuming knowledge of is_escape
320	        completions.extend(longs_and_visible_aliases(cmd));
321	        completions.extend(hidden_longs_aliases(cmd));
322	    } else if let Some((flag, value)) = arg.to_long() {
323	        if let Ok(flag) = flag {
324	            if let Some(value) = value {
325	                if let Some(arg) = cmd.get_arguments().find(|a| a.get_long() == Some(flag)) {
326	                    completions.extend(
327	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
328	                            .into_iter()
329	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
330	                    );
331	                }
332	            } else {
333	                completions.extend(
334	                    longs_and_visible_aliases(cmd)
335	                        .into_iter()
336	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
337	                );
338	                completions.extend(
339	                    hidden_longs_aliases(cmd)
340	                        .into_iter()
341	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
342	                );
343	            }
344	        }
345	    } else if let Some(short) = arg.to_short() {
346	        if !short.is_negative_number() {
347	            // Find the first takes_values option.
348	            let (leading_flags, takes_value_opt, mut short) = parse_shortflags(cmd, short);
349	
350	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
351	            if let Some(opt) = takes_value_opt {
352	                let mut peek_short = short.clone();
353	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
354	                    short.next_flag();
355	                    true
356	                } else {
357	                    false
358	                };
359	
360	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
361	                completions.extend(
362	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
363	                        .into_iter()
364	                        .map(|comp| {
365	                            let sep = if has_equal { "=" } else { "" };
366	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
367	                        }),
368	                );
369	            } else {
370	                completions.extend(
371	                    shorts_and_visible_aliases(cmd)
372	                        .into_iter()
373	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
374	                );
375	            }
376	        }
377	    }
378	    debug!("complete_option: completions={completions:?}");
379	    completions
380	}
