382	fn complete_arg_value(
383	    value: Result<&str, &OsStr>,
384	    arg: &clap::Arg,
385	    current_dir: Option<&std::path::Path>,
386	    arg_index: usize,
387	) -> Vec<CompletionCandidate> {
388	    let mut values = Vec::new();
389	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
390	
391	    let (prefix, value) =
392	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
393	
394	    let value_os = match value {
395	        Ok(value) => OsStr::new(value),
396	        Err(value_os) => value_os,
397	    };
398	
399	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
400	        values.extend(completer.complete_at(arg_index, value_os));
401	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
402	        values.extend(complete_value_candidates(
403	            value_os,
404	            completer.value_candidates(),
405	        ));
406	    } else if let Some(possible_values) = possible_values(arg) {
407	        if let Ok(value) = value {
408	            values.extend(complete_candidates_str(
409	                value,
410	                possible_value_candidates(possible_values),
411	            ));
412	        }
413	    } else {
414	        match arg.get_value_hint() {
415	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
416	                // Should not complete
417	            }
418	            clap::ValueHint::AnyPath => {
419	                values.extend(complete_path(value_os, current_dir, &|_| true));
420	            }
421	            clap::ValueHint::FilePath => {
422	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
423	            }
424	            clap::ValueHint::DirPath => {
425	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
426	            }
427	            clap::ValueHint::ExecutablePath => {
428	                use is_executable::IsExecutable;
429	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
430	            }
431	            clap::ValueHint::CommandName
432	            | clap::ValueHint::CommandString
433	            | clap::ValueHint::CommandWithArguments
434	            | clap::ValueHint::Username
435	            | clap::ValueHint::Hostname
436	            | clap::ValueHint::Url
437	            | clap::ValueHint::EmailAddress => {
438	                // No completion implementation
439	            }
440	            _ => {
441	                // Safe-ish fallback
442	                values.extend(complete_path(value_os, current_dir, &|_| true));
443	            }
444	        }
445	
446	        values.sort();
447	    }
448	
449	    if let Some(prefix) = prefix {
450	        values = values
451	            .into_iter()
452	            .map(|comp| comp.add_prefix(prefix))
453	            .collect();
454	    }
455	    values = values
456	        .into_iter()
457	        .map(|comp| {
458	            if comp.get_tag().is_some() {
459	                comp
460	            } else {
461	                comp.tag(Some(arg.to_string().into()))
462	            }
463	        })
464	        .collect();
465	
466	    debug!("complete_arg_value: values={values:?}");
467	    values
468	}
