470	fn rsplit_delimiter<'s, 'o>(
471	    value: Result<&'s str, &'o OsStr>,
472	    delimiter: Option<char>,
473	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
474	    let delimiter = delimiter?;
475	    let value = value.ok()?;
476	    let pos = value.rfind(delimiter)?;
477	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
478	    Some((Some(prefix), Ok(value)))
479	}
480	
481	fn complete_value_candidates(
482	    value: &OsStr,
483	    completer: &dyn ValueCandidates,
484	) -> Vec<CompletionCandidate> {
485	    debug!("complete_value_candidates: value={value:?}");
486	
487	    let mut values = completer.candidates();
488	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
489	    values
490	}
491	
492	fn complete_candidates_str(
493	    value: &str,
494	    mut values: Vec<CompletionCandidate>,
495	) -> Vec<CompletionCandidate> {
496	    debug!("complete_candidates_str: value={value:?}");
497	
498	    values.retain(|comp| comp.get_value().starts_with(value));
499	    values
500	}
501	
502	fn complete_value_candidates_str(
503	    value: &str,
504	    completer: &dyn ValueCandidates,
505	) -> Vec<CompletionCandidate> {
506	    debug!("complete_value_candidates_str: value={value:?}");
507	
508	    complete_candidates_str(value, completer.candidates())
509	}
510	
511	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
512	    debug!(
513	        "complete_subcommand: cmd={:?}, value={:?}",
514	        cmd.get_name(),
515	        value
516	    );
517	
518	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
519	        .into_iter()
520	        .filter(|x| x.get_value().starts_with(value))
521	        .collect();
522	    if cmd.is_allow_external_subcommands_set() {
523	        let external_completer = cmd.get::<SubcommandCandidates>();
524	        if let Some(completer) = external_completer {
525	            scs.extend(complete_value_candidates_str(
526	                value,
527	                completer.value_candidates(),
528	            ));
529	        }
530	    }
531	
532	    scs.sort();
533	    scs.dedup();
534	    scs
535	}
